using System;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Threading.Tasks;
using System.Windows.Forms;

public sealed class HardwareDiscoveryDialog : Form {
    readonly string profile,root=AppDomain.CurrentDomain.BaseDirectory;readonly Func<Dictionary<string,object>> snapshot;
    readonly DataGridView grid=new BufferedDataGridView();readonly TextBox queries=new TextBox(),report=new TextBox();readonly Label progress=new Label();readonly Button run=new ReadableButton(),close=new ReadableButton();readonly CheckBox local=new ReadableCheckBox();readonly Timer timer=new Timer();string output,last="";bool busy;
    public string PublicReport{get{return report.Text;}}
    public HardwareDiscoveryDialog(string profileDirectory,Func<Dictionary<string,object>> currentSnapshot){
        profile=profileDirectory;snapshot=currentSnapshot;Text="Hardware discovery - read only";Icon=ThermalBrand.CreateIcon();Size=new Size(1100,750);MinimumSize=new Size(800,550);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(18,23,31);ForeColor=Color.White;Font=new Font("Segoe UI",10);
        var layout=new BufferedTableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Padding=new Padding(12)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,75));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));Controls.Add(layout);
        progress.Dock=DockStyle.Fill;progress.ForeColor=Color.Aquamarine;progress.Text="Read-only discovery lists driver/BMC-exposed sensors. No fan speed or cooling setting is changed.\r\nUnavailable resources and driver access are reported; a listed channel is not proof that fan writes work.";layout.Controls.Add(progress,0,0);
        var tabs=new BufferedTabControl{Dock=DockStyle.Fill};layout.Controls.Add(tabs,0,1);var sensors=new TabPage("Sensors and devices"){BackColor=BackColor};var checks=new TabPage("Queries / access"){BackColor=BackColor};var publicPage=new TabPage("Public support report"){BackColor=BackColor};tabs.TabPages.AddRange(new[]{sensors,checks,publicPage});sensors.Controls.Add(grid);checks.Controls.Add(queries);publicPage.Controls.Add(report);
        grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.RowHeadersVisible=false;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.BackgroundColor=BackColor;grid.EnableHeadersVisualStyles=false;grid.DefaultCellStyle.BackColor=Color.FromArgb(29,36,47);grid.DefaultCellStyle.ForeColor=Color.White;grid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(37,47,61);grid.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;
        foreach(string column in new[]{"Backend","Type","Name","Query identifier","Reading","Units","Access / capability"})grid.Columns.Add(column,column);grid.Columns[2].FillWeight=160;grid.Columns[3].FillWeight=190;
        foreach(var text in new[]{queries,report}){text.Dock=DockStyle.Fill;text.Multiline=true;text.ReadOnly=true;text.ScrollBars=ScrollBars.Both;text.WordWrap=false;text.BackColor=BackColor;text.ForeColor=Color.LightGreen;text.Font=new Font("Consolas",9);}
        var buttons=new BufferedFlowLayoutPanel{Dock=DockStyle.Fill};run.Text="Run read-only discovery";run.Width=210;run.Height=34;run.Click+=async(s,e)=>await Scan();local.Text="Include this PC's hardware";local.AutoSize=true;local.Margin=new Padding(10,8,10,0);var config=ProfileStore.Read(profile);local.Checked=Convert.ToString(config.ContainsKey("ManagementProvider")?config["ManagementProvider"]:null)=="Local";close.Text="Use report / close";close.Width=180;close.Height=34;close.Click+=(s,e)=>{DialogResult=DialogResult.OK;Close();};buttons.Controls.Add(run);buttons.Controls.Add(local);buttons.Controls.Add(close);layout.Controls.Add(buttons,0,2);
        timer.Interval=500;timer.Tick+=(s,e)=>ReadProgress();FormClosing+=(s,e)=>{if(busy){e.Cancel=true;progress.Text="Discovery is still running. The scan has time limits; existing cooling workers are unaffected.";}};FormClosed+=(s,e)=>{timer.Stop();timer.Dispose();if(output!=null){try{File.Delete(output);}catch{}}};
        Shown+=async(s,e)=>{if(!FanApp.PreviewMode)await Scan();};
    }
    static string Value(Dictionary<string,object> d,string key){return d!=null&&d.ContainsKey(key)?Convert.ToString(d[key]):"";}
    void ReadProgress(){try{if(output==null||!File.Exists(output))return;string raw=File.ReadAllText(output);if(raw==last)return;last=raw;var data=ProfileStore.Json.Deserialize<Dictionary<string,object>>(raw);grid.Rows.Clear();var rows=data.ContainsKey("Rows")?data["Rows"] as IEnumerable:null;if(rows!=null)foreach(var item in rows){var row=item as Dictionary<string,object>;grid.Rows.Add(Value(row,"Backend"),Value(row,"Kind"),Value(row,"Name"),Value(row,"Identifier"),Value(row,"Value"),Value(row,"Units"),Value(row,"Access"));}var lines=new List<string>();var checks=data.ContainsKey("Checks")?data["Checks"] as IEnumerable:null;if(checks!=null)foreach(var item in checks){var row=item as Dictionary<string,object>;lines.Add(Value(row,"Backend")+" | "+Value(row,"Query")+" | "+Value(row,"Result"));}queries.Text=String.Join(Environment.NewLine,lines.ToArray());progress.Text=Value(data,"Phase")+" | "+grid.Rows.Count+" sensor/device/locator rows | "+lines.Count+" queries completed\r\nRead only. Empty results can mean missing permissions, driver/BMC limitations or unsupported resources.";
        }catch(IOException){}catch(System.ArgumentException){}catch(System.InvalidOperationException){}}
    async Task Scan(){
        if(busy)return;report.Clear();busy=true;run.Enabled=local.Enabled=close.Enabled=false;last="";output=Path.Combine(Path.GetTempPath(),"ThermalOps-discovery-"+Guid.NewGuid().ToString("N")+".json");string file=output;bool include=local.Checked;var config=ProfileStore.Read(profile);string host=config.ContainsKey("IdracHost")?Convert.ToString(config["IdracHost"]):"";bool localOnly=include&&(host=="127.0.0.1"||host=="localhost"||host=="");
        try{timer.Start();await Task.Run(()=>{using(var p=new Process()){string script=Path.Combine(root,"ProbeHardware.ps1"),settings=Path.Combine(profile,"settings.json");p.StartInfo=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe"),"-NoProfile -ExecutionPolicy Bypass -File \""+script+"\" -SettingsPath \""+settings+"\" -OutputPath \""+file+"\""+(include?" -IncludeLocal":"")+(localOnly?" -LocalOnly":"")){UseShellExecute=false,CreateNoWindow=true};p.Start();if(!p.WaitForExit(160000)){p.Kill();p.WaitForExit();throw new Exception("Read-only discovery exceeded its time limit.");}if(!File.Exists(file))throw new Exception("Discovery produced no result; check the installed discovery bundle.");}});ReadProgress();var data=ProfileStore.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));report.Text=HardwareSupportReport.CreateWithProbe(snapshot==null?null:snapshot(),data);progress.Text+="\r\nComplete. Review the public report before copying it.";
        }catch(Exception ex){progress.Text="Discovery could not complete: "+ex.Message;}finally{timer.Stop();busy=false;run.Enabled=local.Enabled=close.Enabled=true;}
    }
    public static void Preview(){using(var dialog=new HardwareDiscoveryDialog(AppDomain.CurrentDomain.BaseDirectory,null)){dialog.progress.Text="Example discovery result | 6 sensor/device/locator rows | 4 queries completed\r\nPreview only: no scan was run. Driver-exposed controls have not been exercised.";foreach(var row in new[]{new[]{"IPMI","Temperature","CPU 1","0x0E / entity 3.1","49","C","Read only"},new[]{"IPMI","Fan","Fan1","0x30 / entity 29.1","8400","RPM","Read only"},new[]{"Redfish","Resource","Chassis thermal","/redfish/v1/Chassis/1/Thermal","GET succeeded","","Read only"},new[]{"Local","Temperature","CPU package","/intelcpu/0/temperature/0","50","C","Read only"},new[]{"Local","Control","Motherboard fan","/lpc/it8688e/control/0","40","%","Driver exposes control; writes not tested"},new[]{"Windows","Device","Graphics card","PCI VEN_10DE&DEV_2504","NVIDIA","","Read only"}})dialog.grid.Rows.Add(row);dialog.queries.Text="IPMI | Sensor readings | Read completed\r\nRedfish | GET thermal | Read completed\r\nLocal | Driver sensors | Read completed\r\nLocal | Example optional controller | Unavailable";dialog.Show();Application.DoEvents();using(var bitmap=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(bitmap,new Rectangle(0,0,dialog.Width,dialog.Height));bitmap.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"discovery-preview.png"));}dialog.Hide();}}
}
